class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public boolean exist(char[][] board, String word) {
        boolean[][] visited = new boolean[board.length][board[0].length];
        StringBuilder path = new StringBuilder();
        for (int row = 0; row < board.length; row++) {
            for (int column = 0; column < board[0].length; column++) {
                if (enumerate(board, word.length(), row, column, visited, path, word)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean enumerate(char[][] board, int length, int row, int column, boolean[][] visited, StringBuilder path, String word) {
        if (row < 0 || row >= board.length || column < 0 || column >= board[0].length || visited[row][column]) {
            return false;
        }
        visited[row][column] = true;
        path.append(board[row][column]);
        if (path.length() == length && path.toString().equals(word)) {
            path.deleteCharAt(path.length() - 1);
            visited[row][column] = false;
            return true;
        }
        if (path.length() < length) {
            for (int[] direction : DIRECTIONS) {
                if (enumerate(board, length, row + direction[0], column + direction[1], visited, path, word)) {
                    path.deleteCharAt(path.length() - 1);
                    visited[row][column] = false;
                    return true;
                }
            }
        }
        path.deleteCharAt(path.length() - 1);
        visited[row][column] = false;
        return false;
    }
}

